-- Fresh, explicitly approved empty PostgreSQL target only.
create table public.profiles (id uuid primary key default gen_random_uuid(), email text not null unique, enabled boolean not null default true);
create table public.oidc_identities (issuer text not null, subject text not null, profile_id uuid not null references public.profiles(id), primary key(issuer,subject), unique(profile_id));
create table public.app_sessions (id_hash text primary key, profile_id uuid not null references public.profiles(id), csrf_hash text not null, expires_at timestamptz not null);
create table public.oidc_transactions (id_hash text primary key, state_hash text not null unique, encrypted text not null, return_path text not null, expires_at timestamptz not null);
create table public.app_maintenance (id boolean primary key default true check(id), active boolean not null default false);
insert into public.app_maintenance(id,active) values(true,false);
-- Dedicated Digital Documents project. No existing application tables are changed.
create table public.dd_insurers (id uuid primary key, name text not null);
create table public.dd_catalog (id uuid primary key, insurer_id uuid not null references public.dd_insurers(id), metadata jsonb not null);
create table public.dd_connections (
  user_id uuid not null references public.profiles(id),
  insurer_id uuid not null references public.dd_insurers(id),
  status text not null check (status in ('active', 'disconnected')),
  consent_at timestamptz not null default now(), last_sync_at timestamptz,
  primary key(user_id, insurer_id)
);
create table public.dd_consent_events (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id),
  insurer_id uuid not null references public.dd_insurers(id), action text not null check(action in ('granted','revoked')),
  version text not null default '1.0', locale text not null check(locale in ('de','en')),
  consent_text text not null, created_at timestamptz not null default now()
);
create table public.dd_documents (
  user_id uuid not null references public.profiles(id),
  document_id uuid not null references public.dd_catalog(id), metadata jsonb not null,
  imported_at timestamptz not null default now(), read_at timestamptz,
  primary key(user_id, document_id)
);

alter table public.dd_connections enable row level security;
create policy own_records on public.dd_connections to frida_documents_app using(user_id=nullif(current_setting('frida.user_id',true),'')::uuid) with check(user_id=nullif(current_setting('frida.user_id',true),'')::uuid);
alter table public.dd_consent_events enable row level security;
create policy own_records on public.dd_consent_events to frida_documents_app using(user_id=nullif(current_setting('frida.user_id',true),'')::uuid) with check(user_id=nullif(current_setting('frida.user_id',true),'')::uuid);
alter table public.dd_documents enable row level security;
create policy own_records on public.dd_documents to frida_documents_app using(user_id=nullif(current_setting('frida.user_id',true),'')::uuid) with check(user_id=nullif(current_setting('frida.user_id',true),'')::uuid);
create policy backup_read on public.dd_connections for select to frida_documents_backup using(true);
create policy backup_read on public.dd_consent_events for select to frida_documents_backup using(true);
create policy backup_read on public.dd_documents for select to frida_documents_backup using(true);
revoke all on schema public from public;
revoke all on all tables in schema public from public;
